    nOptArgs = 0
    if (present(dims)) nOptArgs = nOptArgs + 1
    if (present(dims8)) nOptArgs = nOptArgs + 1
    if (present(dsource)) nOptArgs = nOptArgs + 1
    if (present(source)) nOptArgs = nOptArgs + 1
